def _warehouse_db(force=False):
    """Verify a pinned provider-search artifact before replacing its local cache."""
    return warehouse_materialize(_WIDX, s3, BUCKET,
                                 "/tmp/justhodl-provider-search.sqlite", _iso(), force=force)


def warehouse_search(q, limit=20, prov=None):
    """Search all cataloged provider objects without loading them into RAM."""
    raw_tokens = [t for t in TOK_RE.findall((q or "").lower())
                  if t not in STOP and len(t) >= 2]
    if not raw_tokens:
        return {"rows": [], "more": False, "facets": [], "integrity": warehouse_cache_evidence(_WIDX, "not_requested")}
    path = _warehouse_db()
    if not path:
        return {"rows": [], "more": False, "facets": [], "integrity": warehouse_cache_evidence(_WIDX, "unavailable")}
    match = " AND ".join('"%s"*' % t for t in raw_tokens[:8])
    sql = (
        "SELECT id,provider,provider_name,title,key,kind,nbytes,age_h,hot "
        "FROM docs WHERE docs MATCH ?")
    args = [match]
    if prov:
        sql += " AND provider=?"
        args.append(prov)
    # Exact catalog entities must beat incidental mentions in long metadata
    # (for example the DXY vault row must beat notes that merely discuss DXY).
    sql += (
        " ORDER BY CASE"
        " WHEN lower(title)=lower(?) THEN 0"
        " WHEN lower(id)=lower(?) OR lower(id) LIKE lower(?) THEN 0"
        " WHEN kind='provider' THEN 1 ELSE 2 END,"
        " bm25(docs), CAST(hot AS INTEGER) DESC LIMIT ?")
    args.extend([q, q, "%:" + q])
    args.append(limit + 1)
    con = sqlite3.connect("file:%s?mode=ro" % path, uri=True)
    try:
        found = con.execute(sql, args).fetchall()
    finally:
        con.close()
    more = len(found) > limit
    found = found[:limit]
    rows = []
    facets = defaultdict(int)
    for rid, provider, provider_name, title, key, rkind, nbytes, age_h, hot in found:
        is_provider = rkind == "provider"
        is_asset = rkind == "asset"
        is_entity = not is_provider and not is_asset
        facets[provider] += 1
        rows.append({
            "id": rid,
            "symbol": title if not is_provider else provider,
            "name": title,
            "provider": provider,
            "provider_name": provider_name or PROV_NAME.get(provider, provider.upper()),
            "kind": "dataset",
            "chartable": False,
            "browse": False,
            "browse_provider": provider if is_provider else None,
            "raw": is_asset,
            "key": (key or None) if is_asset else None,
            "src": (key or None) if is_entity else None,
            "lookup_query": title if is_entity else None,
            "bytes": nbytes,
            "age_h": age_h,
            "hot": bool(hot),
            "catalog_kind": rkind,
        })
    return {
        "rows": rows,
        "integrity": warehouse_cache_evidence(_WIDX, "available"),
        "more": more,
        "facets": [{"provider": p,
                    "provider_name": next(
                        (r["provider_name"] for r in rows
                         if r["provider"] == p), PROV_NAME.get(p, p.upper())),
                    "n": n}
                   for p, n in facets.items()],
    }


def _prefix_range(sorted_pairs, prefix, cap=400):
    lo = bisect.bisect_left(sorted_pairs, (prefix,))
    hi = bisect.bisect_right(sorted_pairs, (prefix + "\uffff",))
    return sorted_pairs[lo:min(hi, lo + cap)], hi - lo


def _expand(tok, toklist, index, cap=250):
    lo = bisect.bisect_left(toklist, tok)
    hi = bisect.bisect_right(toklist, tok + "\uffff")
    cands = toklist[lo:hi]
    if len(cands) > cap:
        exact = [tok] if tok in index else []
        cands = exact + sorted((c for c in cands if c != tok), key=lambda c: -len(index[c]))[:cap]
    return cands


