def doc_tokens(d):
    """Tokens indexed for a doc: title + id parts + provider names + phrase tags + famous aliases."""
    ts = set(tokens(d[D_TITLE]))
    idpart = d[D_ID].split(":", 1)[1] if ":" in d[D_ID] and d[D_PROV] != "tv" else d[D_ID]
    ts.update(tokens(idpart))
    if d[D_KEY]:
        ts.update(t for t in tokens(d[D_KEY])
                  if t not in PATH_STOP and not t.isdigit())
    ts.add(d[D_PROV])
    ts.update(PROV_TOKENS.get(d[D_PROV], ()))
    tt = tokens(d[D_TITLE])
    tset = set(tt)
    for phrase, tag in PHRASE_TAGS:
        if all(w in tset for w in phrase):
            ts.add(tag)
    if d[D_PROV] == "fred":
        fam = FAMOUS.get(d[D_ID].split(":", 1)[1])
        if fam:
            ts.update(tokens(fam))
    # Some providers put the human name below the primary title. Index only
    # bounded descriptive fields, never arbitrary raw payloads.
    ex = d[D_EXTRA] or {}
    for fld in ("aliases", "description", "short_name", "dataset_name"):
        val = ex.get(fld)
        if val:
            if isinstance(val, (list, tuple, set)):
                val = " ".join(str(x) for x in list(val)[:40])
            ts.update(tokens(str(val)[:4000]))
    return ts


