    def st_ofr_fsi():
        # A mandatory first-class stage: absence or schema drift is visible in
        # build errors instead of silently publishing an index without FSI.
        raw = _get("data/warm/ofr-fsi/fsi.csv").decode("utf-8-sig")
        rows = list(csv.DictReader(io.StringIO(raw)))
        headers = list(rows[0]) if rows else []
        if "Date" not in headers or "OFR FSI" not in headers:
            raise ValueError("OFR FSI CSV is empty or missing Date/OFR FSI")
        n = 0
        for col in headers[1:]:
            rid = re.sub(r"[^A-Z0-9]+", "_", col.upper()).strip("_")
            vals = [(r.get("Date"), r.get(col)) for r in rows
                    if r.get(col) not in (None, "")]
            if not vals:
                continue
            title = ("OFR Financial Stress Index" if col == "OFR FSI"
                     else "OFR FSI: " + col)
            docs.append(doc("ofr-fsi:" + rid, "ofr-fsi", title, "series",
                            0.8 if col == "OFR FSI" else 0.58,
                            unit="Index", freq="D", first=vals[0][0],
                            last=vals[-1][0],
                            key="data/warm/ofr-fsi/fsi.csv", n=len(vals),
                            extra={"field": col,
                                   "aliases": [col, "OFR FSI", "financial stress"],
                                   "dataset_name": "OFR Financial Stress Index"}))
            n += 1
        if n < 2:
            raise ValueError("OFR FSI CSV produced fewer than two series")
        return {"series": n, "rows": len(rows)}

    def st_treasury():
        n = 0
        for o in _list("data/warm/treasury/"):
            k = o["Key"]
            if not k.endswith(".json.gz"):
                continue
            d = _get_json(k) or {}
            dsn = d.get("dataset") or k.rsplit("/", 1)[-1][:-8]
            from treasury_fiscal_model import CONTRACT as FISCAL_CONTRACT, measurements
            if d.get("contract") == FISCAL_CONTRACT:
                # One searchable series per field and dimension, never one line
                # blending currencies, security categories or cash-account types.
                for measure in measurements(d):
                    if measure["value"] is None:
                        continue
                    selector = measure["series_id"]
                    title = " / ".join(str(v) for v in measure["dimensions"].values())
                    sid = "treasury:" + dsn + ":" + selector.rsplit(":", 1)[-1]
                    docs.append(doc(sid, "treasury", "FiscalData " + dsn + " / " + measure["field"] + " / " + title,
                                    "series", 0.5, unit=measure["unit"], last=measure["as_of"], key=k,
                                    extra={"ds": dsn, "fiscal_series_id": selector, "dimensional": True}))
                    n += 1
                continue
            obs = d.get("observations")
            if isinstance(obs, list) and obs and isinstance(obs[0], dict) and "date" in obs[0]:
                # the fiscaldata engine already reduced this dataset to one headline series
                vk = next((x for x in obs[0].keys() if x not in ("date", "record_date") and _f(obs[0].get(x)) is not None), "value")
                dates = [o.get("date") for o in obs]
                mixed = len(set(dates)) < 0.9 * len(dates)      # several category rows per date flattened into one list
                docs.append(doc("treasury:" + dsn, "treasury", "FiscalData " + dsn.replace("_", " ") + (" (%s)" % vk.replace("_", " ") if vk != "value" else "") + (" (mixed rows)" if mixed else ""),
                                "series", 0.55 if not mixed else 0.3, unit=d.get("unit"), first=norm_period(min(dates)), last=norm_period(max(dates)),
                                key=k, n=len(obs), extra={"field": vk, "ds": dsn, "mixed": int(mixed)}))
                n += 1
                continue
            rows = d.get("payload") or d.get("data") or d.get("rows") or []
            if isinstance(rows, dict):
                rows = rows.get("data") or []
            if not rows:
                continue
            fields = [f for f in rows[0].keys() if f != "record_date" and _f(rows[0].get(f)) is not None]
            dates = [r.get("record_date") for r in rows]
            unique = len(set(dates)) == len(dates)
            docs.append(doc("treasury:" + dsn, "treasury", "FiscalData " + dsn.replace("_", " "), "dataset", 0.45,
                            n=len(fields) if unique else None, key=k, extra={"unique_dates": unique}))
            if unique:
                for f in fields:
                    docs.append(doc("treasury:%s:%s" % (dsn, f), "treasury", "%s — %s" % (dsn.replace("_", " "), f.replace("_", " ")),
                                    "series", 0.4, unit=d.get("unit"), key=k, n=len(rows), extra={"field": f, "ds": dsn}))
                    n += 1
        return {"series": n}

