def load_index(force=False, check=False):
    return resident_load(_IDX, _ICHECK,
                         lambda: refresh_index(_IDX, s3, BUCKET, SD, index_for_docs, _iso),
                         lambda: index_manifest(s3, BUCKET, SD),
